@Test
public void testNoListUntilUpdateFromRemoteOnPrimaryNodeChange() {
    proc.fileSystem.addFileStatus(new Path("/test"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("/test/testFile.txt")));
    runner.run();
    runner.assertAllFlowFilesTransferred(ListHDFS.REL_SUCCESS, 1);
    final MockFlowFile mff1 = runner.getFlowFilesForRelationship(ListHDFS.REL_SUCCESS).get(0);
    mff1.assertAttributeEquals("path", "/test");
    mff1.assertAttributeEquals("filename", "testFile.txt");
    runner.clearTransferState();
    // add new file to pull
    proc.fileSystem.addFileStatus(new Path("/test"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("/test/testFile2.txt")));
    // trigger primary node change
    proc.onPrimaryNodeChange(PrimaryNodeState.ELECTED_PRIMARY_NODE);
    // cause calls to service to fail
    service.failOnCalls = true;
    runner.run();
    runner.assertAllFlowFilesTransferred(ListHDFS.REL_SUCCESS, 0);
    runner.run();
    runner.assertAllFlowFilesTransferred(ListHDFS.REL_SUCCESS, 0);
    final String key = proc.getKey("/test");
    // wait just to a bit to ensure that the timestamp changes when we update the service
    final Object curVal = service.values.get(key);
    try {
        Thread.sleep(10L);
    } catch (final InterruptedException ie) {
    }
    service.failOnCalls = false;
    runner.run();
    runner.assertAllFlowFilesTransferred(ListHDFS.REL_SUCCESS, 1);
    // ensure state saved both locally & remotely
    assertTrue(proc.localStateSaved);
    assertNotNull(service.values.get(key));
    assertNotSame(curVal, service.values.get(key));
}

@Test
public void testExtract() throws IOException {
    final TestRunner runner = TestRunners.newTestRunner(ExtractHL7Attributes.class);
    runner.enqueue(Paths.get("src/test/resources/hypoglycemia.hl7"));
    runner.run();
    runner.assertAllFlowFilesTransferred(ExtractHL7Attributes.REL_SUCCESS, 1);
    final MockFlowFile out = runner.getFlowFilesForRelationship(ExtractHL7Attributes.REL_SUCCESS).get(0);
    final SortedMap<String, String> sortedAttrs = new TreeMap<>(out.getAttributes());
    int mshSegmentCount = 0;
    int obrSegmentCount = 0;
    int obxSegmentCount = 0;
    int pidSegmentCount = 0;
    for (final Map.Entry<String, String> entry : sortedAttrs.entrySet()) {
        final String entryKey = entry.getKey();
        if (entryKey.startsWith("MSH")) {
            mshSegmentCount++;
            continue;
        } else if (entryKey.startsWith("OBR")) {
            obrSegmentCount++;
            continue;
        } else if (entryKey.startsWith("OBX")) {
            obxSegmentCount++;
            continue;
        } else if (entryKey.startsWith("PID")) {
            pidSegmentCount++;
            continue;
        }
    }
    Assert.assertEquals("Did not have the proper number of MSH segments", 8, mshSegmentCount);
    Assert.assertEquals("Did not have the proper number of OBR segments", 9, obrSegmentCount);
    Assert.assertEquals("Did not have the proper number of OBX segments", 9, obxSegmentCount);
    Assert.assertEquals("Did not have the proper number of PID segments", 6, pidSegmentCount);
}

