    try (final OutputStream out = new FileOutputStream(file)) {
        out.write(0);
        out.write(0);
    }
    try {
        try (final StandardTocReader reader = new StandardTocReader(file)) {
            assertFalse(reader.isCompressed());
        }
    } finally {
        file.delete();
    }
    try (final OutputStream out = new FileOutputStream(file)) {
        out.write(0);
        out.write(1);
    }
    try {
        try (final StandardTocReader reader = new StandardTocReader(file)) {
            assertTrue(reader.isCompressed());
        }
    } finally {
        file.delete();
    }
}

