    runner.assertAllFlowFilesTransferred(ControlRate.REL_SUCCESS, 4);
    runner.clearTransferState();
    runner.run();
    runner.assertTransferCount(ControlRate.REL_SUCCESS, 0);
    runner.assertTransferCount(ControlRate.REL_FAILURE, 0);
